from PIL import Image
import codecs
import pytesseract

IMAGE_PATH = "image.png"

def task_func(filename=IMAGE_PATH, from_encoding="cp1251", to_encoding="utf8"):
    try:
        # Check if the file exists and is an image file
        if not filename or not Image.open(filename).is_animated:
            raise ValueError("Invalid image file provided")

        # Open the image
        img = Image.open(filename)

        # Extract text from the image using OCR
        try:
            text = pytesseract.image_to_string(img, lang='rus')
            if text:
                # Convert text encoding
                try:
                    text_converted = text.encode(from_encoding, errors='strict').decode(to_encoding)
                    return text_converted
                except (UnicodeDecodeError, LookupError):
                    raise ValueError("Invalid encoding provided")
        except Exception:
            pass  # OCR extraction failed, proceed to comment extraction

        # If OCR extraction fails, try image comment
        try:
            comment = img.getcomment()
            if comment:
                try:
                    comment_converted = comment.encode(from_encoding, errors='strict').decode(to_encoding)
                    return comment_converted
                except (UnicodeDecodeError, LookupError):
                    raise ValueError("Invalid encoding provided")
        except Exception:
            pass  # Comment extraction failed, return empty string

    except (ValueError, UnicodeDecodeError, LookupError):
        raise

    # If both OCR extraction and comment processing fail
    return ""
